  SELECT order_id FROM silver.orders WHERE order_date >= DATE '2026-09-01' AND order_date < DATE '2026-10-01'
),
returned_orders AS (
  SELECT DISTINCT order_id FROM silver.returns WHERE order_id IN (SELECT order_id FROM sep_orders)
)
